import { useEffect, useState } from "react";
import { collection, getDocs, addDoc, deleteDoc, doc, serverTimestamp } from "firebase/firestore";
import Navbar from "../components/Navbar";
import { CHANGELOG } from "../data/changelog";
import { useAuth } from "../context/AuthContext";
import { db } from "../firebase";
import "./NoticePage.css";

function fmtDate(ts) {
  if (!ts) return "";
  const d = ts.toDate ? ts.toDate() : new Date(ts);
  return `${d.getFullYear()}.${String(d.getMonth() + 1).padStart(2, "0")}.${String(d.getDate()).padStart(2, "0")}`;
}

function fmtCheerTime(ts) {
  if (!ts) return "";
  const d = ts.toDate ? ts.toDate() : new Date(ts);
  return `${String(d.getMonth() + 1).padStart(2, "0")}.${String(d.getDate()).padStart(2, "0")} ${String(d.getHours()).padStart(2, "0")}:${String(d.getMinutes()).padStart(2, "0")}`;
}

const CHEER_PAGE_SIZE = 5;
const CHEER_ROTATE_MS = 5000;

export default function NoticePage() {
  const { currentUser, canEditNetworking: canEdit } = useAuth();
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [writing, setWriting] = useState(false);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");
  const [saving, setSaving] = useState(false);

  const [cheers, setCheers] = useState([]);
  const [cheerText, setCheerText] = useState("");
  const [cheerSaving, setCheerSaving] = useState(false);
  const [cheerPage, setCheerPage] = useState(0);

  useEffect(() => {
    async function load() {
      try {
        const snap = await getDocs(collection(db, "notices"));
        const data = snap.docs.map((d) => ({ ...d.data(), _id: d.id }));
        data.sort((a, b) => (b.createdAt?.seconds ?? 0) - (a.createdAt?.seconds ?? 0));
        setPosts(data);
      } catch {
        setPosts([]);
      }
      setLoading(false);
    }
    load();
  }, []);

  useEffect(() => {
    async function load() {
      try {
        const snap = await getDocs(collection(db, "cheers"));
        const data = snap.docs.map((d) => ({ ...d.data(), _id: d.id }));
        data.sort((a, b) => (b.createdAt?.seconds ?? 0) - (a.createdAt?.seconds ?? 0));
        setCheers(data);
      } catch {
        setCheers([]);
      }
    }
    load();
  }, []);

  useEffect(() => {
    if (cheers.length <= CHEER_PAGE_SIZE) return;
    const pageCount = Math.ceil(cheers.length / CHEER_PAGE_SIZE);
    const timer = setInterval(() => {
      setCheerPage((p) => (p + 1) % pageCount);
    }, CHEER_ROTATE_MS);
    return () => clearInterval(timer);
  }, [cheers.length]);

  const handleSubmit = async () => {
    if (!title.trim() || !content.trim() || saving) return;
    setSaving(true);
    try {
      const data = {
        title: title.trim(),
        content: content.trim(),
        authorName: currentUser?.displayName || currentUser?.email || "익명",
        createdAt: serverTimestamp(),
      };
      const docRef = await addDoc(collection(db, "notices"), data);
      setPosts((prev) => [{ ...data, createdAt: { seconds: Date.now() / 1000 }, _id: docRef.id }, ...prev]);
      setTitle("");
      setContent("");
      setWriting(false);
    } finally {
      setSaving(false);
    }
  };

  const handleCheerSubmit = async () => {
    if (!cheerText.trim() || cheerSaving || !currentUser) return;
    setCheerSaving(true);
    try {
      const data = {
        content: cheerText.trim(),
        authorName: currentUser?.displayName || currentUser?.email || "익명",
        createdAt: serverTimestamp(),
      };
      const docRef = await addDoc(collection(db, "cheers"), data);
      setCheers((prev) => [{ ...data, createdAt: { seconds: Date.now() / 1000 }, _id: docRef.id }, ...prev]);
      setCheerText("");
      setCheerPage(0);
    } finally {
      setCheerSaving(false);
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("이 공지를 삭제할까요?")) return;
    await deleteDoc(doc(db, "notices", id));
    setPosts((prev) => prev.filter((p) => p._id !== id));
  };

  return (
    <div className="noticePage">
      <Navbar />
      <main className="noticeWrap">
        <div className="noticeHeaderRow">
          <h1 className="noticeTitle">공지사항</h1>
          {canEdit && !writing && (
            <button className="noticeWriteBtn" onClick={() => setWriting(true)}>
              + 글쓰기
            </button>
          )}
        </div>

        <section className="cheerBoard">
          <div className="cheerInputRow">
            <textarea
              className="cheerInput"
              placeholder={currentUser ? "응원 메시지를 남겨주세요" : "로그인 후 응원 메시지를 남길 수 있어요"}
              rows={2}
              value={cheerText}
              disabled={!currentUser}
              onChange={(e) => setCheerText(e.target.value)}
            />
            <button
              className="cheerSendBtn"
              onClick={handleCheerSubmit}
              disabled={!currentUser || cheerSaving || !cheerText.trim()}
            >
              {cheerSaving ? "전송 중…" : "응원하기"}
            </button>
          </div>
          {!currentUser && <p className="cheerLoginNotice">로그인하면 응원 메시지를 남길 수 있어요.</p>}
          {cheers.length === 0 ? (
            <p className="cheerEmpty">아직 응원 메시지가 없어요.</p>
          ) : (
            <ul className="cheerList">
              {cheers.slice(cheerPage * CHEER_PAGE_SIZE, cheerPage * CHEER_PAGE_SIZE + CHEER_PAGE_SIZE).map((c) => (
                <li className="cheerItem" key={c._id}>
                  <span className="cheerContent">{c.content}</span>
                  <span className="cheerTime">{fmtCheerTime(c.createdAt)}</span>
                </li>
              ))}
            </ul>
          )}
        </section>

        {writing && (
          <div className="noticeWriteForm">
            <input
              className="noticeWriteTitle"
              placeholder="제목"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
            <textarea
              className="noticeWriteContent"
              placeholder="내용을 입력하세요"
              rows={5}
              value={content}
              onChange={(e) => setContent(e.target.value)}
            />
            <div className="noticeWriteActions">
              <button className="noticeWriteCancelBtn" onClick={() => { setWriting(false); setTitle(""); setContent(""); }}>
                취소
              </button>
              <button className="noticeWriteSubmitBtn" onClick={handleSubmit} disabled={saving || !title.trim() || !content.trim()}>
                {saving ? "등록 중…" : "등록"}
              </button>
            </div>
          </div>
        )}

        {!loading && posts.length > 0 && (
          <section className="noticeSection">
            {posts.map((p) => (
              <div className="noticeRelease" key={p._id}>
                <div className="noticePostHeader">
                  <div>
                    <div className="noticePostTitle">{p.title}</div>
                    <div className="noticeReleaseDate">
                      {fmtDate(p.createdAt)}{p.authorName ? ` · ${p.authorName}` : ""}
                    </div>
                  </div>
                  {canEdit && (
                    <button className="noticePostDeleteBtn" onClick={() => handleDelete(p._id)}>삭제</button>
                  )}
                </div>
                <p className="noticePostContent">{p.content}</p>
              </div>
            ))}
          </section>
        )}

        <section className="noticeSection">
          {CHANGELOG.map((release) => (
            <div className="noticeRelease" key={release.version}>
              <div className="noticeReleaseDate">{release.date}</div>
              <ul className="noticeList">
                {release.items.map((item, i) => (
                  <li key={i}>{item}</li>
                ))}
              </ul>
            </div>
          ))}
        </section>
      </main>
    </div>
  );
}
